// ServerInterface represents all server handlers.
type ServerInterface interface {
	// DsarListIntakeForms Public web intake forms (DSAR-01)
	// (GET /admin/v1/dsar/forms)
	DsarListIntakeForms(w http.ResponseWriter, r *http.Request, params DsarListIntakeFormsParams)
	// DsarCreateIntakeForm Open a new draft intake form for a legal entity (DSAR-01)
	// (POST /admin/v1/dsar/forms)
	DsarCreateIntakeForm(w http.ResponseWriter, r *http.Request, params DsarCreateIntakeFormParams)
	// DsarGetIntakeForm One intake form (DSAR-01)
	// (GET /admin/v1/dsar/forms/{id})
	DsarGetIntakeForm(w http.ResponseWriter, r *http.Request, id Uuid, params DsarGetIntakeFormParams)
	// DsarPublishIntakeForm Make a draft (or re-publish a retired) intake form live (DSAR-01) — issues a platform.public_keys key
	// (POST /admin/v1/dsar/forms/{id}/publish)
	DsarPublishIntakeForm(w http.ResponseWriter, r *http.Request, id Uuid, params DsarPublishIntakeFormParams)
	// DsarRetireIntakeForm Retire an intake form for good (DSAR-01) — its key stops resolving, past requests are untouched
	// (POST /admin/v1/dsar/forms/{id}/retire)
	DsarRetireIntakeForm(w http.ResponseWriter, r *http.Request, id Uuid, params DsarRetireIntakeFormParams)
	// DsarListLegalHolds Every legal hold on record, newest first (DSAR-10, ม.33)
	// (GET /admin/v1/dsar/legal-holds)
	DsarListLegalHolds(w http.ResponseWriter, r *http.Request, params DsarListLegalHoldsParams)
	// DsarCreateLegalHold Record a legal hold — data this tenant must keep despite an otherwise-valid erasure request (DSAR-10, ม.33)
	// (POST /admin/v1/dsar/legal-holds)
	DsarCreateLegalHold(w http.ResponseWriter, r *http.Request, params DsarCreateLegalHoldParams)
	// DsarDeactivateLegalHold Deactivate a legal hold (soft — is_active=false, never deleted) (DSAR-10)
	// (DELETE /admin/v1/dsar/legal-holds/{id})
	DsarDeactivateLegalHold(w http.ResponseWriter, r *http.Request, id Uuid, params DsarDeactivateLegalHoldParams)
	// DsarListRequestTypes The 9 fixed DSAR right types (dsar.requests.request_type_id), for the request form's picker
	// (GET /admin/v1/dsar/request-types)
	DsarListRequestTypes(w http.ResponseWriter, r *http.Request, params DsarListRequestTypesParams)
	// DsarListRequests The tenant's DSAR requests (ST-02)
	// (GET /admin/v1/dsar/requests)
	DsarListRequests(w http.ResponseWriter, r *http.Request, params DsarListRequestsParams)
	// DsarCreateRequest Receive a DSAR request (the minimal slice of DSAR-01/02 that DSAR-13 needs — a full intake form/channel is a sibling feature)
	// (POST /admin/v1/dsar/requests)
	DsarCreateRequest(w http.ResponseWriter, r *http.Request, params DsarCreateRequestParams)
	// DsarGetRequest One DSAR request
	// (GET /admin/v1/dsar/requests/{id})
	DsarGetRequest(w http.ResponseWriter, r *http.Request, id Uuid, params DsarGetRequestParams)
	// DsarListAgents Every agent record for this request, oldest first (DSAR-04, ม.20)
	// (GET /admin/v1/dsar/requests/{id}/agents)
	DsarListAgents(w http.ResponseWriter, r *http.Request, id Uuid, params DsarListAgentsParams)
	// DsarRecordAgent Record who submitted this request on the data subject's own behalf, with their authority-proof document (DSAR-04, ม.20)
	// (POST /admin/v1/dsar/requests/{id}/agents)
	DsarRecordAgent(w http.ResponseWriter, r *http.Request, id Uuid, params DsarRecordAgentParams)
	// DsarVerifyAgent Staff confirm the agent's own authority document (DSAR-04 — "ยืนยันทั้งผู้ยื่นและเจ้าของข้อมูล", no trusted registry to check it against automatically)
	// (POST /admin/v1/dsar/requests/{id}/agents/{agentId}/verify)
	DsarVerifyAgent(w http.ResponseWriter, r *http.Request, id Uuid, agentId Uuid, params DsarVerifyAgentParams)
	// DsarAssignRequest Set (or clear) the request's responsible person (If-Match) — DSAR-07, notified alongside role DPO when the SLA reminder fires.
	// (POST /admin/v1/dsar/requests/{id}/assign)
	DsarAssignRequest(w http.ResponseWriter, r *http.Request, id Uuid, params DsarAssignRequestParams)
	// DsarListExemptionChecks Every exemption check run against this request, newest first (DSAR-10, ม.33)
	// (GET /admin/v1/dsar/requests/{id}/exemption-checks)
	DsarListExemptionChecks(w http.ResponseWriter, r *http.Request, id Uuid, params DsarListExemptionChecksParams)
	// DsarRunExemptionCheck Check the given assets against every active legal hold before an erasure request can complete (DSAR-10, ม.33)
	// (POST /admin/v1/dsar/requests/{id}/exemption-checks)
	DsarRunExemptionCheck(w http.ResponseWriter, r *http.Request, id Uuid, params DsarRunExemptionCheckParams)
	// DsarGeneratePortabilityExport Generate a machine-readable export of this request's own subject data (DSAR-15, ม.31) and package it for secure delivery (DSAR-14)
	// (POST /admin/v1/dsar/requests/{id}/export)
	DsarGeneratePortabilityExport(w http.ResponseWriter, r *http.Request, id Uuid, params DsarGeneratePortabilityExportParams)
	// DsarListPackages Secure delivery packages sent for this request, newest first (DSAR-14)
	// (GET /admin/v1/dsar/requests/{id}/packages)
	DsarListPackages(w http.ResponseWriter, r *http.Request, id Uuid, params DsarListPackagesParams)
	// DsarCreatePackage Package an already-attached file for secure delivery (DSAR-14) — a loginless link, expiring per the setting, optionally gated by a one-time access code
	// (POST /admin/v1/dsar/requests/{id}/packages)
	DsarCreatePackage(w http.ResponseWriter, r *http.Request, id Uuid, params DsarCreatePackageParams)
	// DsarListSubtasks Every subtask of this request (DSAR-08), oldest first
	// (GET /admin/v1/dsar/requests/{id}/subtasks)
	DsarListSubtasks(w http.ResponseWriter, r *http.Request, id Uuid, params DsarListSubtasksParams)
	// DsarCreateSubtask Assign a subtask of this request to a system owner or team (DSAR-08) — notifies the assignee
	// (POST /admin/v1/dsar/requests/{id}/subtasks)
	DsarCreateSubtask(w http.ResponseWriter, r *http.Request, id Uuid, params DsarCreateSubtaskParams)
	// DsarDeleteSubtask Remove a subtask from a request (DSAR-08)
	// (DELETE /admin/v1/dsar/requests/{id}/subtasks/{subtaskId})
	DsarDeleteSubtask(w http.ResponseWriter, r *http.Request, id Uuid, subtaskId Uuid, params DsarDeleteSubtaskParams)
	// DsarUpdateSubtaskStatus Move a subtask along open → in_progress → done|not_applicable (If-Match) — only the assignee (user or their group), or a caller holding dsar.subtask.execute, may change a subtask they do not own
	// (POST /admin/v1/dsar/requests/{id}/subtasks/{subtaskId}/status)
	DsarUpdateSubtaskStatus(w http.ResponseWriter, r *http.Request, id Uuid, subtaskId Uuid, params DsarUpdateSubtaskStatusParams)
	// DsarTransitionRequest Move a request along ST-02 (If-Match). Entering awaiting_info/completed/rejected auto-generates the matching response letter draft (DSAR-13) — the caller also needs dsar.request.update for that document-composer write.
	// (POST /admin/v1/dsar/requests/{id}/transition)
	DsarTransitionRequest(w http.ResponseWriter, r *http.Request, id Uuid, params DsarTransitionRequestParams)
	// DsarListVerifications Every identity-verification attempt against this request, oldest first (DSAR-06)
	// (GET /admin/v1/dsar/requests/{id}/verifications)
	DsarListVerifications(w http.ResponseWriter, r *http.Request, id Uuid, params DsarListVerificationsParams)
	// DsarSubmitIdDocumentVerification Redact the ID-card number in the uploaded photo (the given rectangles only) before it is ever stored — the raw upload is never attached (DSAR-06's acceptance criterion); opens a pending verification for staff to decide
	// (POST /admin/v1/dsar/requests/{id}/verifications/id-document)
	DsarSubmitIdDocumentVerification(w http.ResponseWriter, r *http.Request, id Uuid, params DsarSubmitIdDocumentVerificationParams)
	// DsarStartOtpVerification Send a fresh OTP to the request's own stored contact (IAM-05) and open a verification attempt — moves the request received → verifying the first time this is called
	// (POST /admin/v1/dsar/requests/{id}/verifications/otp)
	DsarStartOtpVerification(w http.ResponseWriter, r *http.Request, id Uuid, params DsarStartOtpVerificationParams)
	// DsarConfirmOtpVerification Check a submitted OTP code — success sets dsar.requests.verified_at and moves verifying → in_review (DSAR-06's acceptance criterion)
	// (POST /admin/v1/dsar/requests/{id}/verifications/{verificationId}/confirm-otp)
	DsarConfirmOtpVerification(w http.ResponseWriter, r *http.Request, id Uuid, verificationId Uuid, params DsarConfirmOtpVerificationParams)
	// DsarDecideVerification Staff decision on a pending id_document verification after checking it against system records — passing sets dsar.requests.verified_at and moves verifying → in_review
	// (POST /admin/v1/dsar/requests/{id}/verifications/{verificationId}/decide)
	DsarDecideVerification(w http.ResponseWriter, r *http.Request, id Uuid, verificationId Uuid, params DsarDecideVerificationParams)
}

