// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// DsarListIntakeForms Public web intake forms (DSAR-01)
	// (GET /admin/v1/dsar/forms)
	DsarListIntakeForms(ctx context.Context, request DsarListIntakeFormsRequestObject) (DsarListIntakeFormsResponseObject, error)
	// DsarCreateIntakeForm Open a new draft intake form for a legal entity (DSAR-01)
	// (POST /admin/v1/dsar/forms)
	DsarCreateIntakeForm(ctx context.Context, request DsarCreateIntakeFormRequestObject) (DsarCreateIntakeFormResponseObject, error)
	// DsarGetIntakeForm One intake form (DSAR-01)
	// (GET /admin/v1/dsar/forms/{id})
	DsarGetIntakeForm(ctx context.Context, request DsarGetIntakeFormRequestObject) (DsarGetIntakeFormResponseObject, error)
	// DsarPublishIntakeForm Make a draft (or re-publish a retired) intake form live (DSAR-01) — issues a platform.public_keys key
	// (POST /admin/v1/dsar/forms/{id}/publish)
	DsarPublishIntakeForm(ctx context.Context, request DsarPublishIntakeFormRequestObject) (DsarPublishIntakeFormResponseObject, error)
	// DsarRetireIntakeForm Retire an intake form for good (DSAR-01) — its key stops resolving, past requests are untouched
	// (POST /admin/v1/dsar/forms/{id}/retire)
	DsarRetireIntakeForm(ctx context.Context, request DsarRetireIntakeFormRequestObject) (DsarRetireIntakeFormResponseObject, error)
	// DsarListLegalHolds Every legal hold on record, newest first (DSAR-10, ม.33)
	// (GET /admin/v1/dsar/legal-holds)
	DsarListLegalHolds(ctx context.Context, request DsarListLegalHoldsRequestObject) (DsarListLegalHoldsResponseObject, error)
	// DsarCreateLegalHold Record a legal hold — data this tenant must keep despite an otherwise-valid erasure request (DSAR-10, ม.33)
	// (POST /admin/v1/dsar/legal-holds)
	DsarCreateLegalHold(ctx context.Context, request DsarCreateLegalHoldRequestObject) (DsarCreateLegalHoldResponseObject, error)
	// DsarDeactivateLegalHold Deactivate a legal hold (soft — is_active=false, never deleted) (DSAR-10)
	// (DELETE /admin/v1/dsar/legal-holds/{id})
	DsarDeactivateLegalHold(ctx context.Context, request DsarDeactivateLegalHoldRequestObject) (DsarDeactivateLegalHoldResponseObject, error)
	// DsarListRequestTypes The 9 fixed DSAR right types (dsar.requests.request_type_id), for the request form's picker
	// (GET /admin/v1/dsar/request-types)
	DsarListRequestTypes(ctx context.Context, request DsarListRequestTypesRequestObject) (DsarListRequestTypesResponseObject, error)
	// DsarListRequests The tenant's DSAR requests (ST-02)
	// (GET /admin/v1/dsar/requests)
	DsarListRequests(ctx context.Context, request DsarListRequestsRequestObject) (DsarListRequestsResponseObject, error)
	// DsarCreateRequest Receive a DSAR request (the minimal slice of DSAR-01/02 that DSAR-13 needs — a full intake form/channel is a sibling feature)
	// (POST /admin/v1/dsar/requests)
	DsarCreateRequest(ctx context.Context, request DsarCreateRequestRequestObject) (DsarCreateRequestResponseObject, error)
	// DsarGetRequest One DSAR request
	// (GET /admin/v1/dsar/requests/{id})
	DsarGetRequest(ctx context.Context, request DsarGetRequestRequestObject) (DsarGetRequestResponseObject, error)
	// DsarListAgents Every agent record for this request, oldest first (DSAR-04, ม.20)
	// (GET /admin/v1/dsar/requests/{id}/agents)
	DsarListAgents(ctx context.Context, request DsarListAgentsRequestObject) (DsarListAgentsResponseObject, error)
	// DsarRecordAgent Record who submitted this request on the data subject's own behalf, with their authority-proof document (DSAR-04, ม.20)
	// (POST /admin/v1/dsar/requests/{id}/agents)
	DsarRecordAgent(ctx context.Context, request DsarRecordAgentRequestObject) (DsarRecordAgentResponseObject, error)
	// DsarVerifyAgent Staff confirm the agent's own authority document (DSAR-04 — "ยืนยันทั้งผู้ยื่นและเจ้าของข้อมูล", no trusted registry to check it against automatically)
	// (POST /admin/v1/dsar/requests/{id}/agents/{agentId}/verify)
	DsarVerifyAgent(ctx context.Context, request DsarVerifyAgentRequestObject) (DsarVerifyAgentResponseObject, error)
	// DsarAssignRequest Set (or clear) the request's responsible person (If-Match) — DSAR-07, notified alongside role DPO when the SLA reminder fires.
	// (POST /admin/v1/dsar/requests/{id}/assign)
	DsarAssignRequest(ctx context.Context, request DsarAssignRequestRequestObject) (DsarAssignRequestResponseObject, error)
	// DsarListExemptionChecks Every exemption check run against this request, newest first (DSAR-10, ม.33)
	// (GET /admin/v1/dsar/requests/{id}/exemption-checks)
	DsarListExemptionChecks(ctx context.Context, request DsarListExemptionChecksRequestObject) (DsarListExemptionChecksResponseObject, error)
	// DsarRunExemptionCheck Check the given assets against every active legal hold before an erasure request can complete (DSAR-10, ม.33)
	// (POST /admin/v1/dsar/requests/{id}/exemption-checks)
	DsarRunExemptionCheck(ctx context.Context, request DsarRunExemptionCheckRequestObject) (DsarRunExemptionCheckResponseObject, error)
	// DsarGeneratePortabilityExport Generate a machine-readable export of this request's own subject data (DSAR-15, ม.31) and package it for secure delivery (DSAR-14)
	// (POST /admin/v1/dsar/requests/{id}/export)
	DsarGeneratePortabilityExport(ctx context.Context, request DsarGeneratePortabilityExportRequestObject) (DsarGeneratePortabilityExportResponseObject, error)
	// DsarListPackages Secure delivery packages sent for this request, newest first (DSAR-14)
	// (GET /admin/v1/dsar/requests/{id}/packages)
	DsarListPackages(ctx context.Context, request DsarListPackagesRequestObject) (DsarListPackagesResponseObject, error)
	// DsarCreatePackage Package an already-attached file for secure delivery (DSAR-14) — a loginless link, expiring per the setting, optionally gated by a one-time access code
	// (POST /admin/v1/dsar/requests/{id}/packages)
	DsarCreatePackage(ctx context.Context, request DsarCreatePackageRequestObject) (DsarCreatePackageResponseObject, error)
	// DsarListSubtasks Every subtask of this request (DSAR-08), oldest first
	// (GET /admin/v1/dsar/requests/{id}/subtasks)
	DsarListSubtasks(ctx context.Context, request DsarListSubtasksRequestObject) (DsarListSubtasksResponseObject, error)
	// DsarCreateSubtask Assign a subtask of this request to a system owner or team (DSAR-08) — notifies the assignee
	// (POST /admin/v1/dsar/requests/{id}/subtasks)
	DsarCreateSubtask(ctx context.Context, request DsarCreateSubtaskRequestObject) (DsarCreateSubtaskResponseObject, error)
	// DsarDeleteSubtask Remove a subtask from a request (DSAR-08)
	// (DELETE /admin/v1/dsar/requests/{id}/subtasks/{subtaskId})
	DsarDeleteSubtask(ctx context.Context, request DsarDeleteSubtaskRequestObject) (DsarDeleteSubtaskResponseObject, error)
	// DsarUpdateSubtaskStatus Move a subtask along open → in_progress → done|not_applicable (If-Match) — only the assignee (user or their group), or a caller holding dsar.subtask.execute, may change a subtask they do not own
	// (POST /admin/v1/dsar/requests/{id}/subtasks/{subtaskId}/status)
	DsarUpdateSubtaskStatus(ctx context.Context, request DsarUpdateSubtaskStatusRequestObject) (DsarUpdateSubtaskStatusResponseObject, error)
	// DsarTransitionRequest Move a request along ST-02 (If-Match). Entering awaiting_info/completed/rejected auto-generates the matching response letter draft (DSAR-13) — the caller also needs dsar.request.update for that document-composer write.
	// (POST /admin/v1/dsar/requests/{id}/transition)
	DsarTransitionRequest(ctx context.Context, request DsarTransitionRequestRequestObject) (DsarTransitionRequestResponseObject, error)
	// DsarListVerifications Every identity-verification attempt against this request, oldest first (DSAR-06)
	// (GET /admin/v1/dsar/requests/{id}/verifications)
	DsarListVerifications(ctx context.Context, request DsarListVerificationsRequestObject) (DsarListVerificationsResponseObject, error)
	// DsarSubmitIdDocumentVerification Redact the ID-card number in the uploaded photo (the given rectangles only) before it is ever stored — the raw upload is never attached (DSAR-06's acceptance criterion); opens a pending verification for staff to decide
	// (POST /admin/v1/dsar/requests/{id}/verifications/id-document)
	DsarSubmitIdDocumentVerification(ctx context.Context, request DsarSubmitIdDocumentVerificationRequestObject) (DsarSubmitIdDocumentVerificationResponseObject, error)
	// DsarStartOtpVerification Send a fresh OTP to the request's own stored contact (IAM-05) and open a verification attempt — moves the request received → verifying the first time this is called
	// (POST /admin/v1/dsar/requests/{id}/verifications/otp)
	DsarStartOtpVerification(ctx context.Context, request DsarStartOtpVerificationRequestObject) (DsarStartOtpVerificationResponseObject, error)
	// DsarConfirmOtpVerification Check a submitted OTP code — success sets dsar.requests.verified_at and moves verifying → in_review (DSAR-06's acceptance criterion)
	// (POST /admin/v1/dsar/requests/{id}/verifications/{verificationId}/confirm-otp)
	DsarConfirmOtpVerification(ctx context.Context, request DsarConfirmOtpVerificationRequestObject) (DsarConfirmOtpVerificationResponseObject, error)
	// DsarDecideVerification Staff decision on a pending id_document verification after checking it against system records — passing sets dsar.requests.verified_at and moves verifying → in_review
	// (POST /admin/v1/dsar/requests/{id}/verifications/{verificationId}/decide)
	DsarDecideVerification(ctx context.Context, request DsarDecideVerificationRequestObject) (DsarDecideVerificationResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

